                               `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                               `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                               `name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '概念名称',
                               `description` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '概念描述',
                               `color` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '概念颜色',
                               `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                               `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                               `create_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                               `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                               `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                               `update_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
                               `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                               `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                               `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
                               PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '概念配置' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ext_schema
-- ----------------------------
INSERT INTO `ext_schema` VALUES (1, 1001, '运维人员', '负责泵站日常巡检、操作及应急处置的工作人员，关联其资质、所属班组及负责区域。', '#3498DB', 1, 0, '吴同', 2, '2026-05-20 09:00:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-人员节点');
INSERT INTO `ext_schema` VALUES (2, 1001, '主机组', '泵站的核心抽水单元，通常指水泵与电动机的组合体，是能量转换的关键设备。', '#E74C3C', 1, 0, '吴同', 2, '2026-05-21 10:30:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-核心资产');
INSERT INTO `ext_schema` VALUES (3, 1001, '机械部件', '构成主机组或辅助设备的独立零件，如轴承、叶轮、密封环、联轴器等，是维修更换的高频对象。', '#F39C12', 1, 0, '吴同', 2, '2026-05-22 14:15:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-组成结构');
INSERT INTO `ext_schema` VALUES (4, 1001, '电气柜', '包含变频器、软启动器、PLC及继电保护装置的集成控制单元，负责设备的启停与逻辑控制。', '#9B59B6', 1, 0, '吴同', 2, '2026-05-23 08:45:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-控制系统');
INSERT INTO `ext_schema` VALUES (5, 1001, '阀门管件', '用于截断水流、调节流量或防止倒流的装置，包括蝶阀、止回阀、闸阀及伸缩节等。', '#E67E22', 1, 0, '吴同', 2, '2026-05-24 11:20:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-管网系统');
INSERT INTO `ext_schema` VALUES (6, 1001, '传感器', '安装在现场用于采集温度、振动、压力、液位等物理量的仪表，是状态监测的数据来源。', '#1ABC9C', 1, 0, '吴同', 2, '2026-05-25 16:00:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-感知层');
INSERT INTO `ext_schema` VALUES (7, 1001, '故障现象', '设备运行异常时的具体表现描述，如“轴承温度过高”、“泵体剧烈振动”、“出水量不足”等。', '#C0392B', 1, 0, '吴同', 2, '2026-05-26 09:30:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-问题域');
INSERT INTO `ext_schema` VALUES (8, 1001, '维修策略', '针对特定故障采取的解决方案或标准作业程序，如“更换机械密封”、“清洗滤网”、“调整间隙”。', '#27AE60', 1, 0, '吴同', 2, '2026-05-27 13:45:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-解决方案');
INSERT INTO `ext_schema` VALUES (9, 1001, '备品备件', '存储在仓库中用于应急替换的材料和零件，关联库存数量、型号规格及适用设备。', '#D35400', 1, 0, '吴同', 2, '2026-05-28 10:00:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-资源库');
INSERT INTO `ext_schema` VALUES (10, 1001, '技术资料', '与设备相关的说明书、图纸、操作规程及历史维修记录，是知识推理的重要依据。', '#7F8C8D', 1, 0, '吴同', 2, '2026-05-29 15:30:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-非结构化数据');
INSERT INTO `ext_schema` VALUES (11, 1001, '运行工况', '记录水泵机组在不同时间段内的实际运行环境与参数组合，如高水位、低流量等，是分析设备疲劳与故障诱因的关键上下文。', '#2980B9', 1, 0, '吴同', 2, '2026-05-30 12:00:00', '吴同', 2, '2026-06-02 14:30:00', '知识图谱-动态运行域');

-- ----------------------------
-- Table structure for ext_schema_attribute
-- ----------------------------
DROP TABLE IF EXISTS `ext_schema_attribute`;
CREATE TABLE `ext_schema_attribute`  (
                                         `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                         `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                         `schema_id` bigint(20) NOT NULL COMMENT '概念id',
                                         `schema_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '概念名称',
                                         `name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '属性名称',
                                         `name_code` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '属性名称代码',
                                         `require_flag` tinyint(1) NOT NULL COMMENT '是否必填',
                                         `data_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '数据类型;0：文本，1：整数，2：小数，3：时间，4：字节类型，5：布尔值',
                                         `dict_type_id` bigint(20) NULL DEFAULT NULL COMMENT '关联字典类型id',
                                         `multiple_flag` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '单/多值;0：单值，1：多值',
                                         `validate_type` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '校验方式;0：唯一性校验，1：长度校验，2：区间校验',
                                         `min_value` decimal(10, 0) NULL DEFAULT NULL COMMENT '最小值（用于区间校验）',
                                         `max_value` decimal(10, 0) NULL DEFAULT NULL COMMENT '最大值（用于区间校验）',
                                         `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                         `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                         `create_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                                         `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                         `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                         `update_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
                                         `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                         `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                         `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
                                         `description` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述',
                                         PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 122 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '概念属性' ROW_FORMAT = DYNAMIC;

