INSERT INTO `ext_schema_attribute` VALUES (118, 1001, 11, '运行工况', '工况结束时间', 'end_time', 1, 3, NULL, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-03 13:14:00', '吴同', 2, '2026-06-02 15:00:00', '时间段结束', '该工况的结束时间点');
