-- ----------------------------
-- Table structure for ext_schema_relation
-- ----------------------------
DROP TABLE IF EXISTS `ext_schema_relation`;
CREATE TABLE `ext_schema_relation`  (
                                        `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                        `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                        `start_schema_id` bigint(20) NOT NULL COMMENT '起点概念id',
                                        `relation` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '关系',
                                        `end_schema_id` bigint(20) NOT NULL COMMENT '终点概念id',
                                        `inverse_flag` tinyint(1) NOT NULL COMMENT '是否可逆',
                                        `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                        `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                        `create_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                                        `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                        `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                        `update_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
                                        `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                        `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                        `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
                                        `description` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述',
                                        PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '关系配置' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ext_schema_relation
-- ----------------------------
INSERT INTO `ext_schema_relation` VALUES (1, 1001, 1, '负责', 2, 1, 1, 0, '吴同', 2, '2026-05-20 09:15:00', '吴同', 2, '2026-06-02 14:45:49', '运维人员-主机组', '运维人员与主机组之间的责任关系。运维人员负责主机组的日常巡检、设备操作、运行监控及应急处置工作。该关系具有可逆性，即主机组也可查询其对应的负责运维人员。');
INSERT INTO `ext_schema_relation` VALUES (2, 1001, 2, '由组成', 3, 0, 1, 0, '吴同', 2, '2026-05-20 10:30:00', '吴同', 2, '2026-06-02 15:30:00', '主机组-机械部件', '主机组与机械部件之间的组成关系。主机组由轴承、叶轮、密封环、联轴器等机械部件构成，这些部件是主机组实现能量转换功能的基础单元。该关系不可逆向查询。');
INSERT INTO `ext_schema_relation` VALUES (3, 1001, 4, '控制', 2, 1, 1, 0, '吴同', 2, '2026-05-20 11:45:00', '吴同', 2, '2026-06-02 15:30:00', '电气柜-主机组', '电气柜与主机组之间的控制关系。电气柜通过变频器、软启动器及PLC等装置对主机组进行启停控制、转速调节和运行逻辑管理。该关系具有可逆性，反向关系为“被控制”。');
INSERT INTO `ext_schema_relation` VALUES (4, 1001, 5, '连接', 2, 1, 1, 0, '吴同', 2, '2026-05-20 14:00:00', '吴同', 2, '2026-06-02 15:30:00', '阀门管件-主机组', '阀门管件与主机组之间的连接关系。阀门管件安装在主机组的进出水口，用于截断水流、调节流量或防止倒流。该关系具有可逆性，反向关系为“被连接”。');
INSERT INTO `ext_schema_relation` VALUES (5, 1001, 6, '采集', 2, 0, 1, 0, '吴同', 2, '2026-05-20 15:20:00', '吴同', 2, '2026-06-02 15:30:00', '传感器-主机组', '传感器与主机组之间的数据采集关系。传感器实时采集主机组的温度、振动、压力、转速等运行参数，为状态监测和故障诊断提供数据源。该关系不可逆向查询。');
INSERT INTO `ext_schema_relation` VALUES (6, 1001, 7, '导致', 8, 0, 1, 0, '吴同', 2, '2026-05-20 16:45:00', '吴同', 2, '2026-06-02 15:30:00', '故障现象-维修策略', '故障现象与维修策略之间的因果关系。当主机组出现轴承温度过高、泵体剧烈振动等故障现象时，需要触发并执行对应的维修策略来解决问题。该关系不可逆向查询。');
INSERT INTO `ext_schema_relation` VALUES (7, 1001, 8, '需要', 9, 0, 1, 0, '吴同', 2, '2026-05-21 09:30:00', '吴同', 2, '2026-06-02 15:30:00', '维修策略-备品备件', '维修策略与备品备件之间的需求关系。执行维修策略时，需要消耗特定的备品备件，如更换机械密封、轴承、叶轮等。该关系用于指导维修前的备件准备和库存管理。');
INSERT INTO `ext_schema_relation` VALUES (8, 1001, 10, '描述', 2, 0, 1, 0, '吴同', 2, '2026-05-21 10:50:00', '吴同', 2, '2026-06-02 15:30:00', '技术资料-主机组', '技术资料与主机组之间的描述关系。技术资料包括设备说明书、设计图纸、操作规程及历史维修记录，详细说明了主机组的技术规格、操作方法和维护要求。该关系不可逆向查询。');
INSERT INTO `ext_schema_relation` VALUES (9, 1001, 11, '影响', 2, 0, 1, 0, '吴同', 2, '2026-05-21 13:45:00', '吴同', 2, '2026-06-02 15:30:00', '运行工况-主机组', '运行工况与主机组之间的影响关系。水位变化、流量波动、负荷调整等运行工况直接影响主机组的能耗、效率和设备疲劳程度，是分析故障诱因的重要上下文。该关系不可逆向查询。');
INSERT INTO `ext_schema_relation` VALUES (10, 1001, 3, '属于', 2, 1, 1, 0, '吴同', 2, '2026-05-25 15:10:00', '吴同', 2, '2026-06-02 15:30:00', '机械部件-主机组', '机械部件与主机组之间的归属关系。每个机械部件（如轴承、叶轮）都属于特定的主机组，用于标识部件的位置归属和维修时的设备对应关系。该关系具有可逆性，反向关系为“由组成”。');
INSERT INTO `ext_schema_relation` VALUES (11, 1001, 9, '用于', 8, 0, 1, 0, '吴同', 2, '2026-05-26 17:00:00', '吴同', 2, '2026-06-02 15:30:00', '备品备件-维修策略', '备品备件与维修策略之间的用途关系。备品备件是用于执行维修策略的物料资源，建立了维修活动与库存物资的关联，支撑维修计划的制定和执行。该关系不可逆向查询。');

-- ----------------------------
-- Table structure for ext_struct_task
-- ----------------------------
DROP TABLE IF EXISTS `ext_struct_task`;
CREATE TABLE `ext_struct_task`  (
                                    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                    `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                    `name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务名称',
                                    `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '任务状态;0：未执行，1：进行中：2：已完成',
                                    `publish_status` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '发布状态;0：未发布，1：已发布',
                                    `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
                                    `publisher_id` bigint(20) NULL DEFAULT NULL COMMENT '发布人id',
                                    `publish_by` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '发布人',
                                    `update_type` tinyint(4) NULL DEFAULT 0 COMMENT '更新类型;0：全量更新，1：增量更新',
                                    `update_frequency` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新频率',
                                    `update_status` tinyint(4) NULL DEFAULT 1 COMMENT '定时更新状态（0正常 1暂停）',
                                    `datasource_id` bigint(20) NOT NULL COMMENT '数据源id',
                                    `datasource_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '数据源名称',
                                    `description` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述',
                                    `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                    `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                    `create_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                                    `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                    `update_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
                                    `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                    `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
                                    PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '结构化抽取任务' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ext_struct_task
-- ----------------------------
INSERT INTO `ext_struct_task` VALUES (1, 1001, '泵站维护人员抽取', 2, 0, NULL, NULL, NULL, 0, '0 0/5 * * * ?', 1, 1, '本地数据库', '抽取泵站运维人员岗位、技能资质及排班值守相关人员信息数据。', 0, 0, '吴同', 2, '2026-06-02 17:27:12', '吴同', 2, '2026-06-02 17:29:00', '');
INSERT INTO `ext_struct_task` VALUES (3, 1001, '主机组组成抽取', 2, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '解析泵站主机组结构层级，抽取各核心设备、组件构成及装配关系。', 0, 0, '吴同', 2, '2026-05-15 16:11:09', '吴同', 2, '2026-06-02 17:28:02', '');
INSERT INTO `ext_struct_task` VALUES (4, 1001, '电气柜控制抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '抽取电气柜控制逻辑、启停策略、保护配置及联动控制规则信息。', 0, 0, '吴同', 2, '2026-05-15 16:11:55', '吴同', 2, '2026-05-15 16:11:55', NULL);
INSERT INTO `ext_struct_task` VALUES (5, 1001, '阀门管件连接抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '识别管路拓扑结构，抽取阀门、管件的连接关系、安装位置与流向信息。', 0, 0, '吴同', 2, '2026-05-15 16:12:33', '吴同', 2, '2026-05-15 16:12:33', NULL);
INSERT INTO `ext_struct_task` VALUES (6, 1001, '传感器采集抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '梳理设备测点分布，抽取传感器采集参数、采集频率及对应监测点位。', 0, 0, '吴同', 2, '2026-05-15 16:13:54', '吴同', 2, '2026-05-15 16:13:54', NULL);
INSERT INTO `ext_struct_task` VALUES (7, 1001, '故障现象导致抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '根据设备异常表现，抽取故障现象对应的诱因、表征及衍生异常情况。', 0, 0, '吴同', 2, '2026-05-15 16:14:44', '吴同', 2, '2026-05-15 16:14:44', NULL);
INSERT INTO `ext_struct_task` VALUES (8, 1001, '维修策略需求抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '结合设备工况与故障特征，抽取适配的保养、检修及故障维修策略需求。', 0, 0, '吴同', 2, '2026-05-15 16:15:20', '吴同', 2, '2026-05-15 16:15:20', NULL);
INSERT INTO `ext_struct_task` VALUES (9, 1001, '技术资料描述抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '读取设备台账、说明书资料，结构化抽取设备参数与技术说明信息。', 0, 0, '吴同', 2, '2026-05-15 16:15:59', '吴同', 2, '2026-05-15 16:15:59', NULL);
INSERT INTO `ext_struct_task` VALUES (10, 1001, '运行工况影响抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '抽取设备故障与异常工况，分析对机组运行、产能及设备稳定性的影响。', 0, 0, '吴同', 2, '2026-05-15 16:16:29', '吴同', 2, '2026-05-15 16:16:29', NULL);
