INSERT INTO `ext_struct_task` VALUES (12, 1001, '备品备件用途抽取', 0, 0, NULL, NULL, NULL, 0, '* * * * * ?', 1, 1, '本地数据库', '梳理各类备品备件适配设备，抽取备件用途、替换场景与适用工况信息。', 0, 0, '吴同', 2, '2026-05-15 16:17:49', '吴同', 2, '2026-05-15 16:17:49', NULL);

-- ----------------------------
-- Table structure for ext_struct_temp_pump
-- ----------------------------
DROP TABLE IF EXISTS `ext_struct_temp_pump`;
CREATE TABLE `ext_struct_temp_pump`  (
                                         `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                         `equipment_code` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '设备编号',
                                         `equipment_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '设备名称',
                                         `pump_model` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '水泵型号',
                                         `rated_power` int(11) NULL DEFAULT NULL COMMENT '额定功率(kW)',
                                         `rated_head` decimal(10, 2) NULL DEFAULT NULL COMMENT '额定扬程(m)',
                                         `commissioning_date` datetime NULL DEFAULT NULL COMMENT '投产日期',
                                         `total_runtime` int(11) NULL DEFAULT NULL COMMENT '累计运行时长(小时)',
                                         `current_efficiency` decimal(10, 2) NULL DEFAULT NULL COMMENT '当前效率(%)',
                                         `equipment_photo` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '设备照片',
                                         `is_online` tinyint(4) NULL DEFAULT NULL COMMENT '是否在线',
                                         `sensor_ids` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关联传感器列表',
                                         `user_id` bigint(20) NOT NULL COMMENT '负责人id',
                                         PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '结构化抽取测试数据主机组' ROW_FORMAT = DYNAMIC;

