-- ----------------------------
-- Table structure for ext_unstruct_task
-- ----------------------------
DROP TABLE IF EXISTS `ext_unstruct_task`;
CREATE TABLE `ext_unstruct_task`  (
                                      `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                      `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                      `name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务名称',
                                      `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '任务状态;0：未执行，1：进行中：2：已完成',
                                      `publish_status` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '发布状态;0：未发布，1：已发布',
                                      `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
                                      `publisher_id` bigint(20) NULL DEFAULT NULL COMMENT '发布人id',
                                      `publish_by` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '发布人',
                                      `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                      `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                      `create_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                                      `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                      `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                      `update_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
                                      `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                      `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                      `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
                                      PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '非结构化抽取任务' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ext_unstruct_task
-- ----------------------------
INSERT INTO `ext_unstruct_task` VALUES (24, 1001, '运维人员和维修策略抽取', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-12 15:30:08', '吴同', 2, '2026-06-02 15:30:08', '梳理运维人员资质排班，依据检修案例提炼各类设备维修策略。');
INSERT INTO `ext_unstruct_task` VALUES (25, 1001, '故障现象分析', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-22 16:33:54', '吴同', 2, '2026-06-02 16:33:54', '归集设备报警、参数异常等信息，完整记录故障全过程各类异常表现。');
INSERT INTO `ext_unstruct_task` VALUES (26, 1001, '设备部件清单', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-15 16:22:14', '吴同', 2, '2026-06-02 16:22:14', '拆分整机零部件，标注型号参数，分类梳理关键件与易损配件信息。');
INSERT INTO `ext_unstruct_task` VALUES (27, 1001, '故障原因报告', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-18 16:08:02', '吴同', 2, '2026-06-01 16:08:02', '结合检测与运行数据，多维度溯源故障诱因，汇总成因与佐证资料。');
INSERT INTO `ext_unstruct_task` VALUES (28, 1001, '运行工况影响', 2, 1, '2026-06-02 16:38:00', 1, '吴同', 1, 0, '吴同', 2, '2026-06-02 16:38:00', '吴同', 2, '2026-06-02 16:38:00', '对比故障前后运行参数，分析故障对产能、机组及上下游设备影响。');
INSERT INTO `ext_unstruct_task` VALUES (29, 1001, '震动分析报告', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-02 15:55:04', '吴同', 2, '2026-05-02 15:55:04', '采集测点振动数据对标标准，排查震源，给出设备减振整改意见。');
INSERT INTO `ext_unstruct_task` VALUES (30, 1001, '电机检修规范', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-01 15:45:04', '吴同', 2, '2026-06-01 15:45:04', '规范电机拆解、点检、保养流程，明确检修项目、验收标准与周期要求。');
INSERT INTO `ext_unstruct_task` VALUES (31, 1001, '气蚀特征识别', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-02 15:45:06', '吴同', 2, '2026-05-02 15:45:06', '依托部件外观与介质数据，辨识气蚀形貌，划定易发气蚀设备部位。');
INSERT INTO `ext_unstruct_task` VALUES (32, 1001, '故障原因分析', 2, 1, '2026-06-02 16:37:22', 1, '吴同', 1, 0, '吴同', 2, '2026-06-01 16:37:22', '吴同', 2, '2026-06-01 16:37:22', '结合拆机与日志，分层查找故障根源，梳理故障连锁传导路径。');
INSERT INTO `ext_unstruct_task` VALUES (33, 1001, '故障抢修预案', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-05-10 16:01:06', '吴同', 2, '2026-05-10 16:01:06', '划定故障抢修分工与操作步骤，明确备品工具、分级应急处置方案。');
INSERT INTO `ext_unstruct_task` VALUES (34, 1001, '备件采购规范', 2, 0, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-04-02 16:00:04', '吴同', 2, '2026-04-02 16:00:04', '按损耗速率划分备件类型，明确采购选型、库存标准与审批规则。');

