INSERT INTO `kb_flow_edge` VALUES (161, 1001, 24, 'node_1', 'llm_1774523616282_1', NULL, '{\"id\":\"e-1-source-llm_1774523616282_1-target-1774523616283-1\",\"type\":\"default\",\"source\":\"node_1\",\"target\":\"llm_1774523616282_1\",\"data\":{},\"events\":{},\"label\":\"\",\"style\":{\"stroke\":\"#999\",\"strokeWidth\":2},\"markerEnd\":{\"type\":\"arrowclosed\",\"width\":12,\"height\":12,\"color\":\"#999\"},\"sourceNode\":{\"id\":\"node_1\",\"type\":\"start\",\"dimensions\":{\"width\":200,\"height\":220},\"computedPosition\":{\"x\":100,\"y\":200,\"z\":1000},\"handleBounds\":{\"source\":[{\"type\":\"source\",\"nodeId\":\"node_1\",\"position\":\"right\",\"x\":194,\"y\":105,\"width\":10,\"height\":10}],\"target\":[{\"type\":\"target\",\"nodeId\":\"node_1\",\"position\":\"left\",\"x\":-4,\"y\":105,\"width\":10,\"height\":10}]},\"selected\":true,\"dragging\":false,\"resizing\":false,\"initialized\":false,\"isParent\":false,\"position\":{\"x\":100,\"y\":200},\"data\":{\"input\":[{\"id\":\"text-1774523548353-1\",\"type\":\"text\",\"name\":\"position\",\"label\":\"岗位/职务\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774523563905-4\",\"type\":\"text\",\"name\":\"workPlan\",\"label\":\"下周工作计划\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774523587354-7\",\"type\":\"text\",\"name\":\"workContent\",\"label\":\"本周工作内容\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774523602113-10\",\"type\":\"text\",\"name\":\"problem\",\"label\":\"待处理问题\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false}],\"config\":{\"label\":\"开始\",\"description\":\"\"},\"output\":[]},\"events\":{}},\"targetNode\":{\"id\":\"llm_1774523616282_1\",\"type\":\"llm\",\"dimensions\":{\"width\":200,\"height\":119},\"computedPosition\":{\"x\":420,\"y\":240,\"z\":0},\"handleBounds\":{\"source\":[{\"type\":\"source\",\"nodeId\":\"llm_1774523616282_1\",\"position\":\"right\",\"x\":194,\"y\":54.5,\"width\":10,\"height\":10}],\"target\":[{\"type\":\"target\",\"nodeId\":\"llm_1774523616282_1\",\"position\":\"left\",\"x\":-4,\"y\":54.5,\"width\":10,\"height\":10}]},\"selected\":false,\"dragging\":false,\"resizing\":false,\"initialized\":false,\"isParent\":false,\"position\":{\"x\":420,\"y\":240},\"data\":{\"input\":[{\"id\":\"llm-message-1774523625873-1\",\"role\":\"user\",\"content\":\"岗位/职位：{{ node_1.position }}\\n本周工作内容：{{ node_1.workContent }}\\n下周工作计划：{{ node_1.workPlan }}\\n本周待解决问题：{{ node_1.problem }}\"}],\"config\":{\"label\":\"LLM\",\"description\":\"添加描述...\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"Role: 通用岗位周报格式化生成专家Background:只锁定排版结构、模块顺序、符号规范，不固定任何正文文案、句式、数字，适配全行业全岗位（研发/产品/运营/设计/行政/人事/财务/销售等）。严格对齐固定格式样式，无主标题、无多余抬头、流式输出格式工整不乱。依托用户输入的岗位简称、本周工作、本周待解决问题、下周工作四大核心素材，原生生成专业职场汇报内容，拒绝生硬模板套用。Skills:仅锁排版不变：固定模块顺序、换行规则、符号样式、标题层级，全程不改动格式框架岗位智能优化：根据输入简称自动补全规范职场称谓，输入简称输出标准岗位名内容原生适配：结合岗位属性与用户提供素材，梳理整合专业话术，灵活延展细节、完善逻辑全岗无差别适配：覆盖技术、业务、职能全品类岗位，汇报语气贴合职场正式场景格式零差错输出：严格遵循列表层级、缩进规范，杜绝符号混用、排版错乱岗位智能优化规则：输入岗位简称 → 自动优化为规范称谓，示例：研发 → 研发工程师；产品 → 产品经理；运营 → 运营专员；设计 → UI/UX设计师人事 → 人事专员；财务 → 财务专员；销售 → 销售顾问；行政 → 行政专员其他岗位：在输入简称后补充通用专业后缀，保证称谓得体、职场合规Constraints:禁止生成任何主标题、大标题、周报抬头，杜绝多余标题文字、装饰性话术固定首行原样输出：日期：<自动生成>，禁止修改、替换、填充内容第二行固定格式：岗位：优化后的标准岗位名，严禁变更句式模块顺序、标题层级、列表符号严格固定，不可随意增减、调换模块一级列表固定用1. 2. 3.编号，二级缩进列表固定用空心圆○，严禁更换其他符号正文内容100%基于用户输入素材动态梳理，严禁写死句式、数字、模板话术，杜绝固定文案每条一级条目下，细化内容条数≥3条、随机浮动不固定，贴合业务实际延展固定模块与标题层级（严格按顺序输出，###与文字之间保留空格）：### 本周工作完成情况：一级任务贴合用户输入梳理，1.2.3编号每条一级任务下，用○ 罗列成果、执行细节、交付进度、落地效果等细化内容（≥3条）### 本周待解决问题与跟进情况：问题分类梳理，1.2.3编号每条问题下，用○ 罗列问题描述、当前进展、阻碍因素、协调情况、跟进动作等细化内容（≥3条）### 下周工作计划与目标：一级计划贴合用户输入梳理，1.2.3编号每条一级计划下，用○ 罗列执行步骤、时间节点、交付标准、协同事项、预期目标等细化内容（≥3条）底部固定注释：(注：日期需替换为实际填写周报的日期，内容可根据具体业务细节、数据指标、对接人员补充调整，待解决问题可同步标注跟进时限与责任人。)Workflow:首行固定输出：日期：<自动生成>识别输入岗位简称，按规则优化为标准岗位名，输出第二行岗位信息按固定三级标题顺序，依次拆解用户提供的本周工作、待解决问题、下周工作素材按层级生成列表内容，每条一级条目下补充≥3条细化细节，保证内容饱满、逻辑通顺输出底部固定注释，全程严控格式、流式输出、排版工整\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logpro