INSERT INTO `kb_flow_node` VALUES (93, 1001, 26, 'llm_1780307946032_1', 'LLM', 2, '{\"label\":\"LLM\",\"description\":\"\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"根据用户提交的故障信息，生成精简版故障诊断报告，严格按照以下结构输出：\\n1. 故障简述\\n2. 运行环境\\n3. 核心根因\\n4. 修复步骤（简洁可直接执行）\\n5. 风险提示\\n6. 预防建议\\n\\n要求：文字精炼，去掉冗余内容，命令单独成行；信息不全则提示补充报错日志、系统版本、操作流程。禁止无关内容。\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logprobs\":false,\"topLogprobs\":0,\"frequencyPenalty\":0,\"responseFormat\":\"\",\"stopSequences\":\"\",\"memoryEnabled\":false,\"visionEnabled\":false,\"reasoningTagEnabled\":false,\"structuredOutputEnabled\":false,\"retryEnabled\":false,\"errorStrategy\":\"none\"}', '{\"id\":\"llm_1780307946032_1\",\"type\":\"llm\",\"dimensions\":{\"width\":200,\"height\":115},\"computedPosition\":{\"x\":420,\"y\":200,\"z\":0},\"handleBounds\":{\"source\":[{\"type\":\"source\",\"nodeId\":\"llm_1780307946032_1\",\"position\":\"right\",\"x\":194,\"y\":52.5,\"width\":10,\"height\":10}],\"target\":[{\"type\":\"target\",\"nodeId\":\"llm_1780307946032_1\",\"position\":\"left\",\"x\":-4,\"y\":52.5,\"width\":10,\"height\":10}]},\"selected\":false,\"dragging\":false,\"resizing\":false,\"initialized\":false,\"isParent\":false,\"position\":{\"x\":420,\"y\":200},\"data\":{\"input\":[{\"id\":\"llm-message-1780364489343-1\",\"role\":\"user\",\"content\":\"{{ start_1.query }}\"}],\"config\":{\"label\":\"LLM\",\"description\":\"\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"根据用户提交的故障信息，生成精简版故障诊断报告，严格按照以下结构输出：\\n1. 故障简述\\n2. 运行环境\\n3. 核心根因\\n4. 修复步骤（简洁可直接执行）\\n5. 风险提示\\n6. 预防建议\\n\\n要求：文字精炼，去掉冗余内容，命令单独成行；信息不全则提示补充报错日志、系统版本、操作流程。禁止无关内容。\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logprobs\":false,\"topLogprobs\":0,\"frequencyPenalty\":0,\"responseFormat\":\"\",\"stopSequences\":\"\",\"memoryEnabled\":false,\"visionEnabled\":false,\"reasoningTagEnabled\":false,\"structuredOutputEnabled\":false,\"retryEnabled\":false,\"errorStrategy\":\"none\"},\"output\":[{\"variableKey\":\"text\",\"variableLabel\":\"