INSERT INTO `kb_flow_node` VALUES (167, 1001, 8, 'llm_1774521623409_1', 'LLM', 2, '{\"label\":\"LLM\",\"description\":\"添加描述...\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"你是一位专业的文本审核助手。我现在有一篇文章，以及用户提供的若干规则和接口数据。请你仔细阅读整篇文章，并根据这些规则和接口数据逐条检查文章中是否存在不符合规范的内容。\\n如果发现任何问题，请以 JSON 格式的对象数组 返回结果，每个对象必须包含以下三个英文字段：\\n\\\"issue\\\"：简要说明违反了哪条规则或存在什么问题。\\n\\\"original_text\\\"：直接引用文章中不符合规则的原文片段（必须与原文完全一致，不要修改或省略）。\\n\\\"suggestion\\\"：针对该问题，提供具体、可行的修改建议，帮助作者改进内容。\\n如果没有发现任何问题，请返回一个空数组：[]\\n请确保：\\n检查覆盖全文，不遗漏任何可能违规的部分；\\n对于同一类规则违规，只要出现在不同位置，就必须作为独立条目分别列出；\\n若有接口数据源，优先依赖接口数据源进行规则判别；\\n\\\"original_text\\\" 必须是原文的精确复制；\\n\\\"suggestion\\\" 要清晰、有建设性，避免模糊或笼统的表述；\\n输出仅包含符合要求的 JSON 数组，不要添加任何额外说明、解释或格式。\\n现在，请根据以下内容开始检查：\\n【文章内容开始】\\n{{ node_1.article }}\\n【文章内容结束】\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logprobs\":false,\"topLogprobs\":0,\"frequencyPenalty\":0,\"responseFormat\":\"\",\"stopSequences\":\"\",\"memoryEnabled\":false,\"visionEnabled\":false,\"reasoningTagEnabled\":false,\"structuredOutputEnabled\":false,\"retryEnabled\":false,\"errorStrategy\":\"none\"}', '{\"id\":\"llm_1774521623409_1\",\"type\":\"llm\",\"dimensions\":{\"width\":200,\"height\":119},\"computedPosition\":{\"x\":420,\"y\":200,\"z\":0},\"handleBounds\":{\"source\":[{\"type\":\"source\",\"nodeId\":\"llm_1774521623409_1\",\"position\":\"right\",\"x\":194,\"y\":54.5,\"width\":10,\"height\":10}],\"target\":[{\"type\":\"target\",\"nodeId\":\"llm_1774521623409_1\",\"position\":\"left\",\"x\":-4,\"y\":54.5,\"width\":10,\"height\":10}]},\"selected\":false,\"dragging\":false,\"resizing\":false,\"initialized\":false,\"isParent\":false,\"position\":{\"x\":420,\"y\":200},\"data\":{\"input\":[{\"id\":\"llm-message-1774521705859-1\",\"role\":\"user\",\"content\":\"【检查规则开始】\\n{{ node_1.rules }}\\n【检查规则结束】\\n【补充规则开始】\\n{{ node_1.rules }}\\n【补充规则结束】\\n【接口数据源开始】\\n{{ node_1.apiRequestList }}\\n【接口数据源结束】\"}],\"config\":{\"label\":\"LLM\",\"description\":\"添加描述...\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"你是一位专业的文本审核助手。我现在有一篇文章，以及用户提供的若干规则和接口数据。请你仔细阅读整篇文章，并根据这些规则和接口数据逐条检查文章中是否存在不符合规范的内容。\\n如果发现任何问题，请以 JSON 格式的对象数组 返回结果，每个对象必须包含以下三个英文字段：\\n\\\"issue\\\"：简要说明违反了哪条规则或存在什么问题。\\n\\\"original_text\\\"：直接引用文章中不符合规则的原文片段（必须与原文完全一致，不要修改或省略）。\\n\\\"suggestion\\\"：针对该问题，提供具体、可行的修改建议，帮助作者改进内容。\\n如果没有发现任何问题，请返回一个空数组：[]\\n请确保：\\n检查覆盖全文，不遗漏任何可能违规的部分；\\n对于同一类规则违规，只要出现在不同位置，就必须作为独立条目分别列出；\\n若有接口数据源，优先依赖接口数据源进行规则判别；\\n\\\"original_text\\\" 必须是原文的精确复制；\\n\\\"suggestion\\\" 要清晰、有建设性，避免模糊或笼统的表述；\\n输出仅包含符合要求的 JSON 数组，不要添加任何额外说明、解释或格式。\\n现在，请根据以下内容开始检查：\\n【文章内容开始】\\n{{ node_1.article }}\\n【文章内容结束】\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logprobs\":false,\"topLogprobs\":0,\"frequencyPenalty\":0,\"responseFormat\":\"\",\"stopSequences\":\"\",\"memoryEnabled\":false,\"visionEnabled\":false,\"reasoningTagEnabled\":false,\"structuredOutputEnabled\":false,\"retryEnabled\":false,\"errorStrategy\":\"none\"},\"output\":[{\"variableKey\":\"text\",\"variableLabel\":\"text\",\"valueType\":\"string\",\"path\":\"text\"}]},\"events\":{}}', '[{\"id\":\"llm-message-1774521705859-1\",\"role\":\"user\",\"content\":\"【检查规则开始】\\n{{ node_1.rules }}\\n【检查规则结束】\\n【补充规则开始】\\n{{ node_1.rules }}\\n【补充规则结束】\\n【接口数据源开始】\\n{{ node_1.apiRequestList }}\\n【接口数据源结束】\"}]', '[{\"variableKey\":\"text\",\"variableLabel\":\"text\",\"valueType\":\"string\",\"path\":\"text\"}]', 1, 0, '吴同', 2, '2026-03-26 18:42:27', '吴同', 2, '2026-03-26 18:42:27', NULL);
