INSERT INTO `kb_flow_node` VALUES (236, 1001, 12, 'start_1', '开始', 1, '{\"label\":\"开始\",\"description\":\"\"}', '{\"id\":\"start_1\",\"type\":\"start\",\"dimensions\":{\"width\":200,\"height\":220},\"computedPosition\":{\"x\":100,\"y\":200,\"z\":0},\"handleBounds\":{\"source\":[{\"type\":\"source\",\"nodeId\":\"start_1\",\"position\":\"right\",\"x\":194,\"y\":105,\"width\":10,\"height\":10}],\"target\":[{\"type\":\"target\",\"nodeId\":\"start_1\",\"position\":\"left\",\"x\":-4,\"y\":105,\"width\":10,\"height\":10}]},\"selected\":false,\"dragging\":false,\"resizing\":false,\"initialized\":false,\"isParent\":false,\"position\":{\"x\":100,\"y\":200},\"data\":{\"input\":[{\"id\":\"text-1774576411206-1\",\"type\":\"text\",\"name\":\"context\",\"label\":\"知识库数据\",\"maxLength\":2000,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774576434453-4\",\"type\":\"text\",\"name\":\"title\",\"label\":\"标题\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774576443357-7\",\"type\":\"text\",\"name\":\"word_count\",\"label\":\"字数\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774576453109-10\",\"type\":\"text\",\"name\":\"subpoints\",\"label\":\"内容要点\",\"maxLength\":1000,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774576463461-13\",\"type\":\"text\",\"name\":\"last_fragment\",\"label\":\"上一段内容\",\"maxLength\":1000,\"defaultValue\":\"\",\"required\":true,\"readonly\":false}],\"config\":{\"label\":\"开始\",\"description\":\"\"},\"output\":[]},\"events\":{}}', '[{\"id\":\"text-1774576411206-1\",\"type\":\"text\",\"name\":\"context\",\"label\":\"知识库数据\",\"maxLength\":2000,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774576434453-4\",\"type\":\"text\",\"name\":\"title\",\"label\":\"标题\",\"maxLength\":48,\"defaultValue\":\"\",\"required\":true,\"readonly\":false},{\"id\":\"text-1774576443357-7\",\"type\":\"tex