INSERT INTO `kb_flow_node` VALUES (288, 1001, 20, 'llm_1774519201153_1', 'LLM', 2, '{\"label\":\"LLM\",\"description\":\"添加描述...\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"你是专注于解决方案、实战干货类文章的标题优化专家，严格遵守以下规则执行任务：\\n\\n1. 输入：仅接收1个任意主题/核心关键词（不限行业、领域、品类）\\n\\n2. 优化要求：\\n   - 针对输入关键词，优化产出5个互不重复、方向差异化的专业标题，拒绝平淡直白、口语化表述\\n   - 风格严谨正式、无营销话术、无夸张修饰、无特殊符号，适配全品类文章、方案文档、干货分享\\n   - 标题突出实用性：体现优化思路、实践方法、解决路径、落地技巧等核心价值\\n\\n3. 输出格式：仅返回标准JSON数组，无编号、无解释、无多余文字、无注释\\n   示例：[\\\"标题1\\\",\\\"标题2\\\",\\\"标题3\\\",\\\"标题4\\\",\\\"标题5\\\"]\\n\\n4. 禁止行为：\\n   - 不生成纯学术标题\\n   - 不随意增删核心关键词\\n   - 不改变JSON格式\\n   - 不偏离用户输入主题\\n   - 不输出多个JSON数组，只输出单个数组\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logprobs\":false,\"topLogprobs\":0,\"frequencyPenalty\":0,\"responseFormat\":\"\",\"stopSequences\":\"\",\"memoryEnabled\":false,\"visionEnabled\":false,\"reasoningTagEnabled\":false,\"structuredOutputEnabled\":false,\"retryEnabled\":false,\"errorStrategy\":\"none\"}', '{\"id\":\"llm_1774519201153_1\",\"type\":\"llm\",\"dimensions\":{\"width\":200,\"height\":115},\"computedPosition\":{\"x\":420,\"y\":200,\"z\":1000},\"handleBounds\":{\"source\":[{\"type\":\"source\",\"nodeId\":\"llm_1774519201153_1\",\"position\":\"right\",\"x\":194,\"y\":52.5,\"width\":10,\"height\":10}],\"target\":[{\"type\":\"target\",\"nodeId\":\"llm_1774519201153_1\",\"position\":\"left\",\"x\":-4,\"y\":52.5,\"width\":10,\"height\":10}]},\"selected\":true,\"dragging\":false,\"resizing\":false,\"initialized\":false,\"isParent\":false,\"position\":{\"x\":420,\"y\":200},\"data\":{\"input\":[{\"id\":\"llm-message-1774519213809-1\",\"role\":\"user\",\"content\":\"标题：{{ node_1.title }}\"}],\"config\":{\"label\":\"LLM\",\"description\":\"添加描述...\",\"provider\":1,\"model\":\"qwen-max\",\"prompt\":\"你是专注于解决方案、实战干货类文章的标题优化专家，严格遵守以下规则执行任务：\\n\\n1. 输入：仅接收1个任意主题/核心关键词（不限行业、领域、品类）\\n\\n2. 优化要求：\\n   - 针对输入关键词，优化产出5个互不重复、方向差异化的专业标题，拒绝平淡直白、口语化表述\\n   - 风格严谨正式、无营销话术、无夸张修饰、无特殊符号，适配全品类文章、方案文档、干货分享\\n   - 标题突出实用性：体现优化思路、实践方法、解决路径、落地技巧等核心价值\\n\\n3. 输出格式：仅返回标准JSON数组，无编号、无解释、无多余文字、无注释\\n   示例：[\\\"标题1\\\",\\\"标题2\\\",\\\"标题3\\\",\\\"标题4\\\",\\\"标题5\\\"]\\n\\n4. 禁止行为：\\n   - 不生成纯学术标题\\n   - 不随意增删核心关键词\\n   - 不改变JSON格式\\n   - 不偏离用户输入主题\\n   - 不输出多个JSON数组，只输出单个数组\",\"temperature\":1,\"maxTokens\":4096,\"topP\":1,\"logprobs\":false,\"topLogprobs\":0,\"frequencyPenalty\":0,\"responseFormat\":\"\",\"stopSequences\":\"\",\"memoryEnabled\":false,\"visionEnabled\":false,\"reasoningTagEnabled\":false,\"structuredOutputEnabled\":false,\"retryEnabled\":false,\"errorStrategy\":\"none\"},\"output\":[{\"variableKey\":\"text\",\"variableLabel\":\"text\",\"valueType\":\"string\",\"path\":\"text\"}]},\"events\":{}}', '[{\"id\":\"llm-message-1774519213809-1\",\"role\":\"user\",\"content\":\"标题：{{ node_1.title }}\"}]', '[{\"variableKey\":\"text\",\"variableLabel\":\"text\",\"valueType\":\"string\",\"path\":\"text\"}]', 1, 0, '吴同', 2, '2026-03-30 12:45:39', '吴同', 2, '2026-03-30 12:45:39', NULL);
