INSERT INTO `kb_runtime` VALUES (40, 1001, 7, '{\"entityCallWord\":\"人物、歌曲\",\"entityAttribute\":\"{\\\"人物\\\":[{\\\"属性名\\\":\\\"名称\\\",\\\"是否必须\\\":\\\"否\\\",\\\"数据类型\\\":\\\"文本\\\"}]}\",\"context\":\"周杰伦唱青花瓷\\n\",\"relationCallWord\":\"创作\"}', '{\"text\":\"```json\\n{\\n    \\\"entities\\\": [\\n        {\\n            \\\"实体文本\\\": \\\"周杰伦\\\",\\n            \\\"实体类型\\\": \\\"人物\\\",\\n            \\\"片段\\\": \\\"周杰伦唱青花瓷\\\",\\n            \\\"属性\\\": {\\n                \\\"名称\\\": \\\"周杰伦\\\"\\n            }\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"青花瓷\\\",\\n            \\\"实体类型\\\": \\\"歌曲\\\",\\n            \\\"片段\\\": \\\"周杰伦唱青花瓷\\\",\\n            \\\"属性\\\": {}\\n        }\\n    ],\\n    \\\"relations\\\": [\\n        {\\n            \\\"头实体\\\": \\\"周杰伦\\\",\\n            \\\"关系\\\": \\\"创作\\\",\\n            \\\"尾实体\\\": \\\"青花瓷\\\"\\n        }\\n    ]\\n}\\n```\"}', 1, 9732, 1, 0, NULL, NULL, '2026-05-11 17:03:39', NULL, NULL, '2026-05-11 17:03:39', NULL);
INSERT INTO `kb_runtime` VALUES (41, 1001, 7, '{\"entityCallWord\":\"器械、材料\",\"context\":\"\\n疾病治疗与干预策略：药物与医疗器械应用指南\\n目录\\n1. 治疗与干预概述\\n2. 药物治疗体系\\n3. 医疗器械应用\\n4. 综合干预策略\\n5. 安全性与有效性评估\\n6. 未来发展趋势\\n1. 治疗与干预概述\\n1.1 基本概念\\n治疗与干预是指通过医学手段对疾病进行控制、缓解或治愈的过程。治疗侧重于疾病本身的处理，而干预更强调预防和早期介入。\\n1.2 治疗目标\\n· 治愈：完全消除疾病\\n· 控制：限制疾病发展\\n· 缓解：减轻症状\\n· 预防：阻止疾病发生\\n1.3 干预层次\\n· 一级预防：疾病发生前的预防\\n· 二级预防：早期发现和治疗\\n· 三级预防：减少疾病并发症\\n2. 药物治疗体系\\n2.1 药物分类\\n2.1.1 按来源分类\\n· 化学合成药物：通过化学方法合成\\n· 生物制剂：来源于生物体或其产物\\n· 天然药物：植物、动物、矿物来源\\n2.1.2 按作用机制分类\\n· 受体激动剂/拮抗剂\\n· 酶抑制剂/激活剂\\n· 离子通道调节剂\\n· 基因表达调节剂\\n2.2 给药途径\\n\\t给药途径\\n\\t特点\\n\\t适用情况\\t口服\\n\\t方便、经济\\n\\t慢性病长期治疗\\t注射\\n\\t起效快、剂量准确\\n\\t急救、重症\\t吸入\\n\\t局部浓度高\\n\\t呼吸系统疾病\\t透皮\\n\\t持续释放\\n\\t长期维持治疗\\n2.3 个体化用药\\n· 基因检测指导用药\\n· 药物代谢动力学优化\\n· 药物相互作用管理\\n· 特殊人群用药调整\\n3. 医疗器械应用\\n3.1 医疗器械分类\\n3.1.1 按风险等级\\n· 一类器械：低风险（如绷带、体温计）\\n· 二类器械：中风险（如血压计、助听器）\\n· 三类器械：高风险（如心脏起搏器、人工心脏瓣膜）\\n3.1.2 按功能分类\\n· 诊断设备：影像设备、检验设备\\n· 治疗设备：手术器械、理疗设备\\n· 辅助设备：康复器械、护理设备\\n3.2 典型医疗器械应用\\n3.2.1 影像诊断设备\\n· X光机：骨骼系统检查\\n· CT扫描仪：断层成像\\n· MRI设备：软组织成像\\n· 超声设备：实时动态成像\\n3.2.2 治疗设备\\n· 心脏起搏器：心律失常治疗\\n· 人工呼吸机：呼吸功能支持\\n· 透析机：肾功能替代\\n· 手术机器人：精准微创手术\\n3.3 智能医疗器械\\n· 可穿戴设备：持续健康监测\\n· 远程医疗设备：居家医疗服务\\n· AI辅助诊断系统：智能分析决策\\n· 3D打印器械：个性化定制\\n4. 综合干预策略\\n4.1 多学科协作模式\\n4.1.1 团队组成\\n· 临床医师：主导治疗决策\\n· 药师：药物治疗管理\\n· 护士：治疗执行与监测\\n· 康复师：功能恢复指导\\n· 营养师：营养支持方案\\n4.1.2 协作流程\\n1. 综合评估：全面了解患者状况\\n2. 方案制定：多学科讨论确定方案\\n3. 执行实施：各专业分工协作\\n4. 效果评价：定期评估调整方案\\n4.2 精准医疗实践\\n4.2.1 分子诊断指导\\n· 基因检测：疾病易感性分析\\n· 蛋白质组学：疾病标志物识别\\n· 代谢组学：个体代谢特征分析\\n4.2.2 个体化治疗方案\\n· 靶向治疗：针对特定分子靶点\\n· 免疫治疗：激活机体免疫系统\\n· 细胞治疗：干细胞、CAR-T等\\n4.3 慢病管理干预\\n4.3.1 糖尿病管理\\n· 药物治疗：胰岛素、口服降糖药\\n· 器械应用：血糖监测仪、胰岛素泵\\n· 生活方式干预：饮食、运动管理\\n4.3.2 心血管疾病管理\\n· 药物治疗：降压药、降脂药\\n· 器械应用：心脏支架、起搏器\\n· 康复干预：心脏康复计划\\n5. 安全性与有效性评估\\n5.1 药物评估体系\\n5.1.1 临床试验阶段\\n· I期：安全性、药代动力学\\n· II期：有效性、剂量探索\\n· III期：大规模验证\\n· IV期：上市后监测\\n5.1.2 风险管控\\n· 不良反应监测：上市后安全性监控\\n· 药物警戒系统：风险信号识别\\n· 风险管理计划：主动风险控制\\n5.2 医疗器械评估\\n5.2.1 审评审批\\n· 技术审评：安全性有效性评价\\n· 临床评价：临床应用验证\\n· 质量体系：生产质量控制\\n5.2.2 上市后监管\\n· 不良事件监测：使用安全性监控\\n· 再评价制度：定期安全性评估\\n· 召回管理：风险产品处置\\n5.3 成本效益分析\\n5.3.1 评价指标\\n· 成本效果比：每获得一个健康效果单位的成本\\n· 质量调整生命年：考虑生命质量的生存时间\\n· 增量成本效果比：新干预与现有干预的成本效果比较\\n5.3.2 决策应用\\n· 医保目录准入：基于成本效果的报销决策\\n· 临床路径优化：性价比最优的治疗选择\\n· 资源配置：医疗资源的合理分配\\n6. 未来发展趋势\\n6.1 创新技术应用\\n6.1.1 人工智能\\n· 智能诊断辅助：影像识别、病理分析\\n· 治疗方案推荐：基于大数据的个性化建议\\n· 药物研发加速：AI辅助药物设计\\n6.1.2 基因编辑技术\\n· 基因治疗：遗传性疾病的根本治疗\\n· 细胞工程：定制化细胞治疗产品\\n· 精准干预：针对特定基因突变的治疗\\n6.2 个性化医疗发展\\n6.2.1 精准诊断\\n· 液体活检：无创肿瘤检测\\n· 多组学分析：全面的个体特征描绘\\n· 实时监测：动态的健康状态跟踪\\n6.2.2 定制化治疗\\n· 3D打印药物：个性化剂量和释放特性\\n· 生物打印器官：解决器官移植短缺\\n· 智能给药系统：按需精准给药\\n6.3 数字化医疗\\n6.3.1 远程医疗\\n· 远程诊断：在线医疗服务\\n· 远程监护：居家健康监测\\n· 远程治疗：虚拟康复指导\\n6.3.2 医疗大数据\\n· 真实世界研究：基于实际医疗数据的疗效评价\\n· 预测分析：疾病风险预测和预防\\n· 决策支持：基于数据的临床决策辅助\\n结语\\n疾病治疗与干预是一个复杂的系统工程，需要综合运用药物、器械等多种手段。随着科技的发展，个性化、精准化的治疗模式正在成为主流。未来，通过人工智能、基因技术、数字化医疗等创新手段的融合应用，我们将能够为患者提供更加安全、有效、便捷的医疗服务。\\n在推进技术创新的同时，我们也要注重治疗的安全性和可及性，确保医疗资源的合理配置和公平分配。只有在科学、伦理、经济等多维度平衡发展的基础上，才能真正实现\\\"以患者为中心\\\"的医疗健康目标。\\n本指南旨在提供疾病治疗与干预的总体框架，具体治疗方案应根据患者个体情况和最新临床证据制定。\\n(AI生成)\",\"relationCallWord\":\"使用\"}', '{\"text\":\"```json\\n{\\n    \\\"entities\\\": [\\n        {\\n            \\\"实体文本\\\": \\\"绷带\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"一类器械：低风险（如绷带、体温计）\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"体温计\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"一类器械：低风险（如绷带、体温计）\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"血压计\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"二类器械：中风险（如血压计、助听器）\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"助听器\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"二类器械：中风险（如血压计、助听器）\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"心脏起搏器\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"三类器械：高风险（如心脏起搏器、人工心脏瓣膜）\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"人工心脏瓣膜\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"三类器械：高风险（如心脏起搏器、人工心脏瓣膜）\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"X光机\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"X光机：骨骼系统检查\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"CT扫描仪\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"CT扫描仪：断层成像\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"MRI设备\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"MRI设备：软组织成像\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"超声设备\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"超声设备：实时动态成像\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"人工呼吸机\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"人工呼吸机：呼吸功能支持\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"透析机\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"透析机：肾功能替代\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"手术机器人\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"手术机器人：精准微创手术\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"可穿戴设备\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"可穿戴设备：持续健康监测\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"远程医疗设备\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"远程医疗设备：居家医疗服务\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"AI辅助诊断系统\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"AI辅助诊断系统：智能分析决策\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"3D打印器械\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"3D打印器械：个性化定制\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"血糖监测仪\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"器械应用：血糖监测仪、胰岛素泵\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"胰岛素泵\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"器械应用：血糖监测仪、胰岛素泵\\\",\\n            \\\"属性\\\": {}\\n        },\\n        {\\n            \\\"实体文本\\\": \\\"心脏支架\\\",\\n            \\\"实体类型\\\": \\\"器械\\\",\\n            \\\"片段\\\": \\\"器械应用：心脏支架、起搏器\\\",\\n            \\\"属性\\\": {}\\n        }\\n    ],\\n    \\\"relations\\\": [\\n        {\\n            \\\"头实体\\\": \\\"心律失常\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"心脏起搏器\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"呼吸功能支持\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"人工呼吸机\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"肾功能替代\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"透析机\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"精准微创手术\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"手术机器人\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"持续健康监测\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"可穿戴设备\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"居家医疗服务\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"远程医疗设备\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"智能分析决策\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"AI辅助诊断系统\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"个性化定制\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"3D打印器械\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"糖尿病管理\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"血糖监测仪\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"糖尿病管理\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"胰岛素泵\\\"\\n        },\\n        {\\n            \\\"头实体\\\": \\\"心血管疾病管理\\\",\\n            \\\"关系\\\": \\\"使用\\\",\\n            \\\"尾实体\\\": \\\"心脏支架\\\"\\n        }\\n    ]\\n}\\n```\"}', 1, 44519, 1, 0, NULL, NULL, '2026-05-15 17:13:43', NULL, NULL, '2026-05-15 17:13:43', NULL);

-- ----------------------------
-- Table structure for kb_runtime_node
-- ----------------------------
DROP TABLE IF EXISTS `kb_runtime_node`;
CREATE TABLE `kb_runtime_node`  (
                                    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                    `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                    `runtime_id` bigint(20) NOT NULL COMMENT '运行时id',
                                    `node_uuid` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点唯一标识',
                                    `step` int(11) NOT NULL COMMENT '步骤号',
                                    `status` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '运行状态;0:执行中，1:成功，2: 失败',
                                    `input` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输入数据',
                                    `output` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输出数据',
                                    `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                    `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                    `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                                    `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                    `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                                    `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                    `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                                    PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 117 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'bot节点运行表' ROW_FORMAT = DYNAMIC;

