-- ----------------------------
-- Table structure for kg_knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `kg_knowledge_document`;
CREATE TABLE `kg_knowledge_document`  (
                                          `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                          `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                          `category_id` bigint(20) NOT NULL COMMENT '知识分类id',
                                          `category_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '知识分类名称',
                                          `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名称',
                                          `path` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件路径',
                                          `description` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件描述',
                                          `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                          `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                          `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                                          `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                          `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                          `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                                          `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                          `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                          `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                                          PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '知识文件表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of kg_knowledge_document
-- ----------------------------
INSERT INTO `kg_knowledge_document` VALUES (1, 1001, 1, '故障现象', '泵站设备故障现象.docx', '/2026/06/02/6a1e35527d3ee200c0f4d3ed.docx', '系统梳理了泵站设备各类典型故障现象，并结合深度机理分析提供了专业的诊断与排查技术指南。', 1, 0, '吴同', 2, '2026-06-02 09:44:01', '吴同', 2, '2026-06-02 09:44:01', '该资料专为泵站运维人员及工程技术人员编写，可作为现场快速排障、日常巡检以及制定预防性维护策略的核心参考依据。');
INSERT INTO `kg_knowledge_document` VALUES (2, 1001, 4, '维修与处置', '泵站设备维修处置策略与预防性维护指南.pdf', '/2026/06/02/6a1e37b87d3ee200c0f4d3ee.pdf', '本指南规范了泵站设备的维修处置与预防性维护流程，旨在保障设备安全高效运行。', 1, 0, '吴同', 2, '2026-06-02 09:55:23', '吴同', 2, '2026-06-02 09:55:23', '文中量化参数为通用参考，实际应用需结合设备手册及现场工况调整；涉及停电上锁等条款须严格遵守国家安全法规');
INSERT INTO `kg_knowledge_document` VALUES (3, 1001, 3, '设备部件', '泵站设备部件清单.xlsx', '/2026/06/02/6a1e394b7d3ee200c0f4d3ef.xlsx', '系统梳理了泵站核心设备的各类基础部件清单，涵盖主水泵机组、高低压电气、闸门启闭机及辅助系统的详细物理组件与规格参数。', 1, 0, '吴同', 2, '2026-06-02 10:06:39', '吴同', 2, '2026-06-02 10:06:39', '该表仅作为设备静态资产台账与部件识别参考，不包含任何动态的维护周期与保养策略信息。');
INSERT INTO `kg_knowledge_document` VALUES (4, 1001, 2, '故障原因', '泵站设备故障原因深度分析报告.docx', '/2026/06/02/6a1e3d277d3ee200c0f4d3f0.docx', '本报告系统剖析了泵站设备典型故障的根本原因，涵盖机械、电气及外部环境等多维度的失效机理与底层逻辑。', 1, 0, '吴同', 2, '2026-06-02 10:19:28', '吴同', 2, '2026-06-02 10:19:28', '报告内容基于历史数据总结，实际应用需结合现场实时参数交叉验证；复杂机电耦合故障的分析结论仅供参考，重大技改或部件更换前建议由原厂复核确认。');
INSERT INTO `kg_knowledge_document` VALUES (5, 1001, 5, '运行工况', '泵站运行工况深度分析报告.pdf', '/2026/06/02/6a1e3e5b7d3ee200c0f4d3f1.pdf', '本文档全面梳理了泵站运行工况的核心要素，详细记录了设备在不同运行模式下的关键参数、水力特性及环境条件，旨在为泵站的日常调度与性能评估提供数据支撑。', 1, 0, '吴同', 2, '2026-06-02 10:22:21', '吴同', 2, '2026-06-02 10:22:21', '文档中的运行参数与工况指标基于当前泵站实际监测数据统计得出，后续若遇设备技改或外部水文条件变化，相关数据需同步更新以确保准确性。');
INSERT INTO `kg_knowledge_document` VALUES (6, 1001, 6, '异常振动', '机组振动测试分析报告.docx', '/2026/06/02/6a1e42117d3ee200c0f4d3f2.docx', '本报告旨在通过分析机组振动测试数据，精准定位设备隐患并为预测性维护提供依据。', 1, 0, '吴同', 2, '2026-06-02 10:40:42', '吴同', 2, '2026-06-02 10:40:42', '本系统自动记录测试分析流程与审核状态，异常处理结果需同步录入以形成闭环');
INSERT INTO `kg_knowledge_document` VALUES (7, 1001, 17, '驱动电机', '电机检修规程.pdf', '/2026/06/02/6a1e43717d3ee200c0f4d3f3.pdf', '本规程旨在规范各类电机的检修周期、作业项目及质量标准，为设备的日常维护与故障处理提供标准化指导。', 1, 0, '吴同', 2, '2026-06-02 10:44:34', '吴同', 2, '2026-06-02 10:44:34', '检修作业须严格执行断电挂牌等安全隔离措施，各项测试数据应如实记录并经专业审核后妥善归档。');
INSERT INTO `kg_knowledge_document` VALUES (8, 1001, 12, '气蚀现象', '气蚀噪声特征分析与识别手册.docx', '/2026/06/02/6a1e452d7d3ee200c0f4d3f4.docx', '本手册系统阐述了流体机械中气蚀噪声的产生机理与物理特性，详细梳理了其在时域波形及高频频谱中的典型特征规律。', 1, 0, '吴同', 2, '2026-06-02 10:51:37', '吴同', 2, '2026-06-02 10:51:37', '在实际应用中需结合多点声学监测数据进行综合比对分析，以有效区分气蚀噪声与常规机械摩擦或流体湍流产生的背景噪音。');
INSERT INTO `kg_knowledge_document` VALUES (9, 1001, 2, '故障原因', '泵站设备故障统计报表.xlsx', '/2026/06/02/6a1e46a37d3ee200c0f4d3f5.xlsx', '本报表专为泵站设备全生命周期管理设计，系统记录并汇总了水泵及配套设施的历史故障、维修成本与运行状态数据。', 1, 0, '吴同', 2, '2026-06-02 10:58:35', '吴同', 2, '2026-06-02 10:58:54', '使用时请结合月度排水量与预防性维护占比进行综合分析，以便为泵站的备件储备和修换决策提供可靠依据。');
INSERT INTO `kg_knowledge_document` VALUES (10, 1001, 21, '故障抢修', '泵站突发故障应急预案手册.docx', '/2026/06/02/6a1e48877d3ee200c0f4d3f6.docx', '本手册系统规定了泵站突发故障的应急组织架构、响应流程与现场处置措施，旨在确保在紧急情况下能迅速高效地开展救援，最大限度减少损失并保障设施安全稳定运行。', 1, 0, '吴同', 2, '2026-06-02 11:05:51', '吴同', 2, '2026-06-02 11:11:41', '实际应用中需结合泵站的具体类型与规模进行针对性调整，相关人员应定期参加培训和演练以熟悉自身职责，并在处置时坚持“以人为本、安全第一”的原则灵活运用。');
INSERT INTO `kg_knowledge_document` VALUES (11, 1001, 22, '零部件更换', '泵站备件采购技术规范书.docx', '/2026/06/02/6a1e49c37d3ee200c0f4d3f7.docx', '本规范书系统梳理了泵站各类备品备件的技术参数与验收标准，旨在确保采购备件的质量可靠、性能匹配且互换性强，从而保障设备运行的连续性与稳定性。', 1, 0, '吴同', 2, '2026-06-02 11:11:14', '吴同', 2, '2026-06-02 11:11:14', '实际应用时应结合设备具体型号与工况进行细化，优先选用原厂或验证合格的替代品，并建立合理的库存储备与使用档案以支撑后续采购决策。');

-- ----------------------------
-- Table structure for kg_knowledge_document_log
-- ----------------------------
DROP TABLE IF EXISTS `kg_knowledge_document_log`;
CREATE TABLE `kg_knowledge_document_log`  (
                                              `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                              `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                              `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户id',
                                              `user_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户名',
                                              `document_id` int(11) NULL DEFAULT NULL COMMENT '文件id',
                                              `document_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名',
                                              `type` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '操作类型;0：预览，1：下载',
                                              `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                              `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                              `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                                              `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                              `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                              `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                                              `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                              `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                              `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                                              PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '文件操作日志' ROW_FORMAT = DYNAMIC;

