INSERT INTO `kmc_category` VALUES (16, 1001, 0, 9, '水泵主体设备故障', 0, '0', 1, 0, '吴同', 2, '2026-06-01 10:24:23', '吴同', 2, '2026-06-01 10:25:21', '泵站核心动力设备故障，为高发故障类型，直接影响输水供水能力，优先排查、重点运维');
INSERT INTO `kmc_category` VALUES (17, 1001, 16, 9, '水泵运行异响振动故障', 1, '0,16', 1, 0, '吴同', 2, '2026-06-01 10:25:59', '吴同', 2, '2026-06-01 10:26:53', '机组运行机械异常，易引发设备松动、磨损损坏');
INSERT INTO `kmc_category` VALUES (18, 1001, 16, 9, '水泵出水异常故障', 2, '0,16', 1, 0, '吴同', 2, '2026-06-01 10:26:12', '吴同', 2, '2026-06-01 10:26:57', '直接导致供水流量、压力不达标，影响泵站输水效能');
INSERT INTO `kmc_category` VALUES (19, 1001, 16, 9, '水泵启停异常故障', 3, '0,16', 1, 0, '吴同', 2, '2026-06-01 10:26:24', '吴同', 2, '2026-06-01 10:27:01', '影响泵站启停联动，易造成设备频繁冲击损坏');
INSERT INTO `kmc_category` VALUES (20, 1001, 0, 9, '泵站电机设备故障', 1, '0', 1, 0, '吴同', 2, '2026-06-01 10:26:35', '吴同', 2, '2026-06-01 10:27:05', '水泵驱动核心设备，故障易导致停机、设备烧毁，存在电气安全隐患');
INSERT INTO `kmc_category` VALUES (21, 1001, 20, 9, '电机温升过热故障', 1, '0,20', 1, 0, '吴同', 2, '2026-06-01 10:26:46', '吴同', 2, '2026-06-01 10:27:09', '过载、散热不良导致，长期高温会烧毁电机线圈');
INSERT INTO `kmc_category` VALUES (22, 1001, 20, 9, '电机异响卡滞故障', 2, '0,20', 1, 0, '吴同', 2, '2026-06-01 10:27:25', '吴同', 2, '2026-06-01 10:27:25', '轴承、转子故障为主，持续运行会造成电机卡死停机');
INSERT INTO `kmc_category` VALUES (23, 1001, 0, 9, '电气控制系统故障', 2, '0', 1, 0, '吴同', 2, '2026-06-01 10:28:06', '吴同', 2, '2026-06-01 10:28:06', '泵站供电、调控核心，故障易造成整机停机、系统断电，影响全站运行');
INSERT INTO `kmc_category` VALUES (24, 1001, 23, 9, '变频器故障', 1, '0,23', 1, 0, '吴同', 2, '2026-06-01 10:28:22', '吴同', 2, '2026-06-01 10:28:22', '调速核心故障，导致泵组调频、调速失效，机组无法稳行');
INSERT INTO `kmc_category` VALUES (25, 1001, 23, 9, '配电柜及线路故障', 2, '0,23', 1, 0, '吴同', 2, '2026-06-01 10:28:37', '吴同', 2, '2026-06-01 10:28:37', '供电线路、柜体部件损坏，引发供电异常');
INSERT INTO `kmc_category` VALUES (26, 1001, 0, 9, '自动化仪表与自控故障', 3, '0', 1, 0, '吴同', 2, '2026-06-01 10:28:56', '吴同', 2, '2026-06-01 10:28:56', '泵站智能运行、数据监测、远程管控核心，故障导致自控失效、数据失真');
INSERT INTO `kmc_category` VALUES (27, 1001, 26, 9, '液位压力流量仪表故障', 1, '0,26', 1, 0, '吴同', 2, '2026-06-01 10:29:20', '吴同', 2, '2026-06-01 10:29:20', '监测数据失真、无数据，导致系统调控判断失误');
INSERT INTO `kmc_category` VALUES (28, 1001, 26, 9, '自动启停联动失效故障', 2, '0,26', 1, 0, '吴同', 2, '2026-06-01 10:29:35', '吴同', 2, '2026-06-01 10:29:35', '无人值守模式下无法自动运行，需人工干预');
INSERT INTO `kmc_category` VALUES (29, 1001, 0, 9, '管路及阀门辅助系统故障', 4, '0', 1, 0, '吴同', 2, '2026-06-01 11:25:25', '吴同', 2, '2026-06-01 11:25:25', '输水流通核心配套系统，故障直接影响输水效率，易引发跑冒滴漏问题');
INSERT INTO `kmc_category` VALUES (30, 1001, 29, 9, '管路堵塞渗漏故障', 1, '0,29', 1, 0, '吴同', 2, '2026-06-01 11:25:37', '吴同', 2, '2026-06-01 11:25:37', '杂物淤积堵塞输水、管路破损渗漏，造成水量损耗、泵房积水');
