INSERT INTO `kmc_category` VALUES (35, 1001, 0, 14, '机械设备故障案例', 0, '0', 1, 0, '吴同', 2, '2026-06-01 14:25:57', '吴同', 2, '2026-06-01 14:25:57', '归集泵站机组机械结构、过流部件、传动密封类真实故障案例，聚焦设备本体硬件损坏、工况异常问题，沉淀机械类故障排查、检修、整改、预防的实战经验，覆盖泵站日常运行高频机械故障场景。');
INSERT INTO `kmc_category` VALUES (36, 1001, 35, 14, '泵体及过流部件故障案例', 1, '0,35', 1, 0, '吴同', 2, '2026-06-01 14:26:13', '吴同', 2, '2026-06-01 14:26:13', '专项收录泵体、叶轮、流道等过流部件故障真实案例，涵盖堵塞、缠绕、磨损、破损、积气、出水异常等问题，记录各类工况下的故障处置流程与复盘经验，解决泵站水力通流类故障问题。');
INSERT INTO `kmc_category` VALUES (37, 1001, 35, 14, '轴承及密封机构故障案例', 2, '0,35', 1, 0, '吴同', 2, '2026-06-01 14:26:27', '吴同', 2, '2026-06-01 14:26:27', '专门汇总轴承、机械密封、填料密封等传动密封结构故障案例，包含异响、过热、磨损、抱死、渗漏超标等常见故障，梳理故障诱因、检修工艺及长效维保防控经验。');
INSERT INTO `kmc_category` VALUES (38, 1001, 0, 14, '电气设备故障案例', 1, '0', 1, 0, '吴同', 2, '2026-06-01 14:26:42', '吴同', 2, '2026-06-01 14:26:42', '收录泵站全套电气设备真实故障案例，聚焦电机、电气线路、开关元件等设备运行异常问题，涵盖跳闸、过载、损坏、运行失常等故障，为电气故障快速排查、安全整改提供案例支撑。');
INSERT INTO `kmc_category` VALUES (39, 1001, 38, 14, '电机运行异常故障案例', 1, '0,38', 1, 0, '吴同', 2, '2026-06-01 14:26:56', '吴同', 2, '2026-06-01 14:26:56', '归集泵站主电机运行全过程异常案例，包含启停故障、过载高温、无故停机、运行不稳等问题，多维度分析故障根源，记录标准化处置流程与隐患整改方案。');
