-- ----------------------------
-- Table structure for kmc_document
-- ----------------------------
DROP TABLE IF EXISTS `kmc_document`;
CREATE TABLE `kmc_document`  (
                                 `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                 `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                 `category_id` bigint(20) NOT NULL COMMENT '知识分类id',
                                 `knowledge_base_id` bigint(20) NULL DEFAULT NULL COMMENT '知识库id',
                                 `knowledge_base_name` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '知识库名称',
                                 `category_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '知识分类名称',
                                 `name` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件名称',
                                 `path` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件路径',
                                 `description` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件描述',
                                 `preview_count` bigint(20) NULL DEFAULT 0 COMMENT '预览次数',
                                 `download_count` bigint(20) NULL DEFAULT 0 COMMENT '下载次数',
                                 `sync_status` tinyint(4) NULL DEFAULT 0 COMMENT '同步状态',
                                 `mode` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分段模式',
                                 `parent_mode` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父分段的召回模式',
                                 `remove_extra_spaces` tinyint(1) NULL DEFAULT NULL COMMENT '替换连续空格、换行符、制表符',
                                 `remove_urls_emails` tinyint(1) NULL DEFAULT NULL COMMENT '删除 URL、电子邮件地址',
                                 `chunk_overlap` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分段重叠',
                                 `max_tokens` int(11) NULL DEFAULT NULL COMMENT '最大长度',
                                 `separator` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '自定义分段标识符',
                                 `subchunk_max_tokens` int(11) NULL DEFAULT NULL COMMENT '子分段最大长度',
                                 `subchunk_separator` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '子分段分隔符',
                                 `doc_form` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '索引内容的形式',
                                 `doc_language` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '在 Q&A 模式下，指定文档的语言',
                                 `chat_model` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对话模型',
                                 `chat_model_provider` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对话模型提供商',
                                 `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                 `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                 `create_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                                 `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                 `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                 `update_by` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
                                 `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                 `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                 `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
                                 PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '知识文件表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of kmc_document
-- ----------------------------
INSERT INTO `kmc_document` VALUES (18, 1001, 17, 9, NULL, '水泵运行异响振动故障', '水泵振动异响、机组晃动故障排查及解决方案.docx', '/2026/06/01/6a1cfd61f0b1d117b2b4628c.docx', '针对泵站运行过程中水泵本体出现异常噪音、机身剧烈振动、机组整体晃动等常见故障，梳理故障诱发原因、分步排查流程、标准化处理方案，同时明确日常巡检、维护预防措施，解决泵组机械运行不稳定问题，规避设备松动、磨损、开裂等次生故障。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:32:59', '吴同', 2, '2026-06-01 11:35:04', NULL);
INSERT INTO `kmc_document` VALUES (19, 1001, 18, 9, NULL, '水泵出水异常故障', '水泵不出水、出水压力不足、流量异常故障排查及解决方案.docx', '/2026/06/01/6a1cff77f0b1d117b2b4628d.docx', '聚焦水泵空转不出水、出水压力偏低/偏高、输水流量不达标、流量波动大等影响输水效能的核心故障，覆盖进水、泵体、出水全链路排查，提供针对性整改方案，保障泵站输水流量、压力满足工艺及供水要求。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:41:53', '吴同', 2, '2026-06-01 11:45:02', NULL);
INSERT INTO `kmc_document` VALUES (20, 1001, 21, 9, NULL, '电机温升过热故障', '电机过热、温升超标、烧毁预警故障排查及解决方案.docx', '/2026/06/01/6a1d00a6f0b1d117b2b4628e.docx', '针对电机运行温升过快、温度超标、机身发烫、高温报警等故障，区分过载、散热不良、电压异常、部件损坏等不同诱因，制定分级排查和整改方案，同时设置烧毁预警处置流程，有效预防电机线圈烧毁、设备报废问题。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:46:56', '吴同', 2, '2026-06-01 11:50:02', NULL);
INSERT INTO `kmc_document` VALUES (21, 1001, 22, 9, NULL, '电机异响卡滞故障', '电机启动失败、卡顿异响、运行无力故障排查及解决方案.docx', '/2026/06/01/6a1d02c0f0b1d117b2b4628f.docx', '解决电机无法启动、启动卡顿、运行异响、动力不足、带载能力差等故障，涵盖机械卡滞、电气缺相、电压不足、轴承损坏等各类问题场景，提供标准化排查步骤和修复方案，保障电机平稳启停、正常带载运行。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:56:03', '吴同', 2, '2026-06-01 12:00:02', NULL);
INSERT INTO `kmc_document` VALUES (22, 1001, 24, 9, NULL, '变频器故障', '变频器报警、故障停机、调频失效排查及解决方案.docx', '/2026/06/01/6a1d030bf0b1d117b2b46290.docx', '针对泵站变频器常见代码报警、突发故障停机、无法调频调速、转速不稳等故障，分类梳理故障类型、报错诱因，细化电气检测、参数调试、硬件检修流程，解决变频器调控失效问题，保障泵组变频稳压、稳流运行。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:57:02', '吴同', 2, '2026-06-01 12:00:03', NULL);
INSERT INTO `kmc_document` VALUES (23, 1001, 25, 9, NULL, '配电柜及线路故障', '泵站电气跳闸、漏电、线路故障排查及解决方案.docx', '/2026/06/01/6a1d039df0b1d117b2b46291.docx', '覆盖泵站配电柜、线缆、开关、接地系统引发的漏电、瞬时跳闸、频繁跳闸、线路发热破损等电气故障，明确安全排查规范、故障定位方法、修复整改措施，消除电气安全隐患，保障电气系统稳定供电。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:59:27', '吴同', 2, '2026-06-01 12:00:04', NULL);
INSERT INTO `kmc_document` VALUES (24, 1001, 27, 9, NULL, '液位压力流量仪表故障', '液位_压力_流量仪表数据不准、无反馈故障排查及解决方案.docx', '/2026/06/01/6a1d1a9ef0b1d117b2b46292.docx', '针对泵站液位、压力、流量传感器仪表数据漂移、数值不准、数据归零、无信号反馈等故障，梳理仪表校准、线路检测、设备检修、安装调试等全套流程，保障监测数据精准，为自控运行提供可靠数据支撑。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:37:36', '吴同', 2, '2026-06-01 13:40:02', NULL);
INSERT INTO `kmc_document` VALUES (25, 1001, 28, 9, NULL, '自动启停联动失效故障', 'PLC联动失效、远程监控通讯中断故障排查及解决方案.docx', '/2026/06/01/6a1d1bcef0b1d117b2b46293.docx', '聚焦PLC程序逻辑异常、设备联动启停失效、现场与后台通讯中断、远程监控无画面、无数据传输等故障，排查程序、模块、网络、线路问题，提供修复及调试方案，保障泵站自动化、远程化正常管控。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:42:41', '吴同', 2, '2026-06-01 13:45:03', NULL);
INSERT INTO `kmc_document` VALUES (26, 1001, 30, 9, NULL, '管路堵塞渗漏故障', '管路渗漏堵塞、阀门卡滞关闭不严故障排查及解决方案.docx', '/2026/06/01/6a1d1cadf0b1d117b2b46294.docx', '针对进出水管道渗漏、堵塞、积水淤积，以及闸阀、止回阀、蝶阀卡滞、开关不到位、关闭不严倒流等故障，制定管路清理、阀门检修、密封更换、管路修补标准化方案，保障管路系统通畅密闭。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:46:24', '吴同', 2, '2026-06-01 13:50:01', NULL);
INSERT INTO `kmc_document` VALUES (27, 1001, 31, 9, NULL, '管路压力异常故障', '过滤器堵塞、泵房积水排水不畅故障排查及解决方案.docx', '/2026/06/01/6a1d1d76f0b1d117b2b46295.docx', '围绕进水过滤器杂物堵塞、滤网淤积、过水不畅，以及泵房集水积水、排水泵启停异常、排水不及时等常见辅助故障，明确日常清理、故障排查、设备检修流程，保障泵房运行环境及输水通畅。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:49:44', '吴同', 2, '2026-06-01 13:50:03', NULL);
INSERT INTO `kmc_document` VALUES (28, 1001, 32, 9, NULL, '泵站配套辅助设备故障', '泵站机组频繁启停、运行不稳定综合故障排查及解决方案.docx', '/2026/06/01/6a1d1e45f0b1d117b2b46296.docx', '针对非人为操作导致的机组频繁启停、运行波动、工况不稳定等综合性疑难故障，整合机械、电气、自控、管路多维度排查逻辑，定位复合型故障诱因，提供综合整改及优化方案，提升泵站整体运行稳定性。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:53:13', '吴同', 2, '2026-06-01 13:55:01', NULL);
INSERT INTO `kmc_document` VALUES (29, 1001, 36, 14, NULL, '泵体及过流部件故障案例', '泵站泵体堵塞、叶轮损坏典型故障案例集.docx', '/2026/06/01/6a1d27b5f0b1d117b2b46299.docx', '收录市政污水泵站、排涝泵站、一体化泵站真实泵体杂物堵塞、纤维缠绕、叶轮磨损断裂、泵腔积气导致不出水的现场故障案例，每例包含故障发生场景、现象特征、现场排查过程、故障根因、整改处置措施及案例复盘总结，可直接用于运维参考与故障对标。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:33:32', '吴同', 2, '2026-06-01 14:54:16', NULL);
INSERT INTO `kmc_document` VALUES (30, 1001, 36, 14, NULL, '泵体及过流部件故障案例', '泵站机组振动、异响超标故障实战案例库.docx', '/2026/06/01/6a1d292df0b1d117b2b4629a.docx', '汇总各类泵站机组运行异响、剧烈振动、共振抖动真实故障案例，区分机械异响、水力异响、管路共振不同故障场景，详细记录案例排查思路、故障点位确认、整改施工过程、整改效果验证及同类问题预防经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\\n\\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:39:45', '吴同', 2, '2026-06-01 14:54:17', NULL);
INSERT INTO `kmc_document` VALUES (31, 1001, 37, 14, NULL, '轴承及密封机构故障案例', '泵站轴承过热、磨损抱死故障案例复盘集.docx', '/2026/06/01/6a1d29a2f0b1d117b2b4629b.docx', '收录机组轴承异响、温升超标、严重磨损、抱死停机等真实故障案例，完整记录每起案例的故障发生过程、运行参数特征、排查检测方式、拆解检修过程、更换整改方案，总结润滑失效、安装偏差、超负荷运行等诱因规律。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:41:42', '吴同', 2, '2026-06-01 14:54:18', NULL);
INSERT INTO `kmc_document` VALUES (32, 1001, 37, 14, NULL, '轴承及密封机构故障案例', '泵站机械密封渗漏、渗水超标故障案例库.docx', '/2026/06/01/6a1d2a20f0b1d117b2b4629c.docx', '整理多场景泵站轴封渗水、机械密封失效、渗漏超标、密封磨损漏水等真实故障案例，还原案例故障现象、排查定位流程、密封更换整改全过程，分析安装、运维、工况波动导致密封损坏的核心原因，沉淀案例处置经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:43:46', '吴同', 2, '2026-06-01 14:54:19', NULL);
INSERT INTO `kmc_document` VALUES (33, 1001, 39, 14, NULL, '电机运行异常故障案例', '泵站轴承过热、磨损抱死故障案例复盘集.docx', '/2026/06/01/6a1d2ab1f0b1d117b2b4629d.docx', '收录各类泵站电机运行过载、电流异常、机身高温、热保护跳闸停机的真实现场案例，详细记录案例运行工况、故障触发条件、多维度排查过程、根因判定、整改措施，梳理机械卡滞、水力过载、电气异常等不同诱因的案例特征。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:46:14', '吴同', 2, '2026-06-01 14:54:20', NULL);
INSERT INTO `kmc_document` VALUES (34, 1001, 39, 14, NULL, '电机运行异常故障案例', '泵站机组启停失败、异常停机故障案例集.docx', '/2026/06/01/6a1d2af5f0b1d117b2b4629e.docx', '汇总机组启动失败、启动瞬间跳闸、运行中无故自动停机、启停卡顿等真实故障案例，还原每起案例故障场景、排查逻辑，区分电气故障、联锁触发、负载异常等不同案例类型，记录标准化处置流程与复盘要点。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:47:20', '吴同', 2, '2026-06-01 14:54:21', NULL);
INSERT INTO `kmc_document` VALUES (35, 1001, 40, 14, NULL, '电气回路及元件故障案例', '泵站电气线路、开关元件故障实战案例库.docx', '/2026/06/01/6a1d2b34f0b1d117b2b4629f.docx', '收录空开频繁跳闸、接触器烧蚀粘连、线路虚接发热、短路断路、端子老化打火等电气真实故障案例，详细记录案例故障现象、检测排查过程、元件更换整改方案，总结日常运维中高频电气隐患案例规律。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:48:23', '吴同', 2, '2026-06-01 14:54:22', NULL);
INSERT INTO `kmc_document` VALUES (36, 1001, 42, 14, NULL, '控制及变频故障案例', '泵站变频器报错、变频异常故障案例复盘.docx', '/2026/06/01/6a1d2b7ef0b1d117b2b462a0.docx', '汇总变频器各类故障代码报警、频率波动、变频无法启动、运行跳闸、低速工况异常等真实现场案例，结合具体案例解读故障代码含义、故障排查步骤、参数优化、硬件整改方案，沉淀变频系统故障处置经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:49:37', '吴同', 2, '2026-06-01 14:54:23', NULL);
INSERT INTO `kmc_document` VALUES (37, 1001, 42, 14, NULL, '控制及变频故障案例', '泵站PLC、控制柜联锁失效故障案例集.docx', '/2026/06/01/6a1d2bc4f0b1d117b2b462a1.docx', '收录PLC程序报错、模块异常、控制柜无输出、设备联锁失效、控制逻辑错乱等自控故障真实案例，完整记录案例故障排查、参数修正、模块检修、逻辑优化全过程，为同类自控故障提供案例对标参考。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:50:46', '吴同', 2, '2026-06-01 14:54:24', NULL);
INSERT INTO `kmc_document` VALUES (38, 1001, 43, 14, NULL, '传感及通讯故障案例', '泵站传感器异常、远程通讯故障案例库.docx', '/2026/06/01/6a1d2c07f0b1d117b2b462a2.docx', '整理液位、压力、流量传感器数据跳变、数据归零、误报警，以及泵站远程通讯中断、监控数据不上传、远程控制失效等真实案例，记录案例故障点位、排查方式、校准修复、线路整改过程及预防方案。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:51:53', '吴同', 2, '2026-06-01 14:54:25', NULL);
INSERT INTO `kmc_document` VALUES (39, 1001, 45, 14, NULL, '机组工况异常故障案例', '泵站机组出力不足、工况异常典型故障案例.docx', '/2026/06/01/6a1d2c4cf0b1d117b2b462a3.docx', '收录水泵出水偏小、扬程不足、流量不稳、机组空转、频繁启停、工况漂移等高频工况异常真实案例，结合不同泵站运行场景，溯源机械、水力、自控系统问题，完整记录案例排查、整改优化过程及长效防控经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:53:03', '吴同', 2, '2026-06-01 14:54:25', NULL);
INSERT INTO `kmc_document` VALUES (40, 1001, 53, 13, NULL, '设备基础知识', '01_设备基础知识.docx', '/2026/06/01/6a1d2f12f0b1d117b2b462a6.docx', '本文件用于整理泵站主要设备的基础知识，包括水泵、电机、阀门、管道、控制柜、传感器等设备的组成、功能、结构特点和基本工作原理，为后续故障排查提供设备认知基础。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\\n\\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 1, '吴同', 2, '2026-06-01 14:54:17', '吴同', 2, '2026-06-01 15:05:24', NULL);
INSERT INTO `kmc_document` VALUES (41, 1001, 53, 13, NULL, '设备基础知识', '泵站主要设备组成结构及工作原理基础知识.docx', '/2026/06/01/6a1d2f4df0b1d117b2b462a8.docx', '用于整理泵站设备运行中常见的故障表现，包括无法启动、异常振动、异响、流量不足、压力异常、设备过热、漏水、跳闸等现象，便于快速识别异常问题。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\\n\\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:05:54', '吴同', 2, '2026-06-01 15:15:01', NULL);
INSERT INTO `kmc_document` VALUES (42, 1001, 54, 13, NULL, '状态监测知识', '泵站运行状态监测指标及关键参数采集知识.docx', '/2026/06/01/6a1d2fb7f0b1d117b2b462a9.docx', '用于整理泵站运行过程中的状态监测内容，包括流量、压力、液位、温度、振动、电流、电压、转速等关键运行参数，帮助判断设备是否处于正常运行状态。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\\n\\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:07:37', '吴同', 2, '2026-06-01 15:15:01', NULL);
INSERT INTO `kmc_document` VALUES (43, 1001, 55, 13, NULL, '故障现象知识', '泵站设备常见故障现象识别与异常表现说明.docx', '/2026/06/01/6a1d2ff3f0b1d117b2b462aa.docx', '用于归纳泵站常见故障表现，如设备无法启动、异响、振动过大、漏水、过热、跳闸等现象。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:08:38', '吴同', 2, '2026-06-01 15:10:03', NULL);
INSERT INTO `kmc_document` VALUES (44, 1001, 56, 13, NULL, '故障原因知识', '泵站设备故障原因分类分析与影响因素说明.docx', '/2026/06/01/6a1d3124f0b1d117b2b462ab.docx', '用于整理泵站常见故障的原因分析，包括机械磨损、电气异常、密封失效、管路堵塞、阀门故障、传感器异常、控制系统故障和操作不当等原因。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:13:43', '吴同', 2, '2026-06-01 15:15:02', NULL);
INSERT INTO `kmc_document` VALUES (45, 1001, 57, 13, NULL, '诊断方法知识', '泵站设备故障诊断方法与现场排查流程知识.docx', '/2026/06/01/6a1d3157f0b1d117b2b462ac.docx', '用于整理泵站故障诊断和排查方法，包括人工巡检、仪表检测、振动分析、温度检测、电气检测、压力流量分析、运行趋势对比等诊断手段。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:14:34', '吴同', 2, '2026-06-01 15:15:03', NULL);
INSERT INTO `kmc_document` VALUES (46, 1001, 58, 13, NULL, '解决方案知识', '泵站常见故障排查步骤与解决方案知识.docx', '/2026/06/01/6a1d319cf0b1d117b2b462ad.docx', '用于整理泵站常见故障的解决方案，包括故障处理思路、排查步骤、处理建议、恢复运行方法和优化改进措施，帮助运维人员快速制定处理方案。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:15:43', '吴同', 2, '2026-06-01 15:20:01', NULL);
INSERT INTO `kmc_document` VALUES (47, 1001, 59, 13, NULL, '维修处理知识', '泵站设备维修处理措施与部件检修更换知识.docx', '/2026/06/01/6a1d31cef0b1d117b2b462ae.docx', '用于整理泵站设备维修处理措施，包括轴承更换、机械密封维修、管道清理、阀门检修、电机维护、控制柜检查、传感器校验等维修内容。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:16:33', '吴同', 2, '2026-06-01 15:20:02', NULL);
INSERT INTO `kmc_document` VALUES (48, 1001, 60, 13, NULL, '典型案例知识', '泵站典型故障案例分析及处理经验总结.docx', '/2026/06/01/6a1d321df0b1d117b2b462af.docx', '用于整理泵站实际运行维护中的典型故障案例，包括故障现象、排查过程、原因分析、处理措施、处理结果和经验总结，为类似问题提供参考。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:17:52', '吴同', 2, '2026-06-01 15:20:03', NULL);
INSERT INTO `kmc_document` VALUES (49, 1001, 61, 13, NULL, '预防维护知识', '泵站设备日常巡检保养与预防性维护知识.docx', '/2026/06/01/6a1d3426f0b1d117b2b462b0.docx', '用于整理泵站设备日常维护和预防性保养知识，包括巡检要求、润滑保养、定期检测、易损件更换、防腐防锈、隐患排查和维护周期安排。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:26:34', '吴同', 2, '2026-06-01 15:30:03', NULL);
INSERT INTO `kmc_document` VALUES (50, 1001, 62, 13, NULL, '安全操作知识', '泵站运行检修安全操作规范与注意事项.docx', '/2026/06/01/6a1d345cf0b1d117b2b462b1.docx', '用于整理泵站运行、检修和维护过程中的安全操作要求，包括设备启停规范、停送电管理、检修防护、现场作业安全、人员防护和注意事项。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:27:30', '吴同', 2, '2026-06-01 15:30:04', NULL);
INSERT INTO `kmc_document` VALUES (51, 1001, 63, 13, NULL, '应急处置知识', '泵站突发故障应急处置流程与抢修方案.docx', '/2026/06/01/6a1d3486f0b1d117b2b462b2.docx', '用于整理泵站突发故障和紧急情况的应急处置流程，包括设备突然停机、管道爆裂、水位异常、电气故障、设备过载、泵房进水等应急处理措施。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:28:08', '吴同', 2, '2026-06-01 15:30:05', NULL);

-- ----------------------------
-- Table structure for kmc_document_log
-- ----------------------------
DROP TABLE IF EXISTS `kmc_document_log`;
CREATE TABLE `kmc_document_log`  (
                                     `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                     `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                     `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户id',
                                     `user_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户名',
                                     `document_id` int(11) NULL DEFAULT NULL COMMENT '文件id',
                                     `document_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名',
                                     `type` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '操作类型;0：预览，1：下载',
                                     `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                     `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                     `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                                     `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                     `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                     `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                                     `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                     `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                     `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                                     PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '文件操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of kmc_document_log
-- ----------------------------

-- ----------------------------
-- Table structure for kmc_document_segment
-- ----------------------------
DROP TABLE IF EXISTS `kmc_document_segment`;
CREATE TABLE `kmc_document_segment`  (
                                         `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                         `workspace_id` bigint(20) NOT NULL COMMENT '工作空间id',
                                         `document_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名称',
                                         `document_id` bigint(20) NOT NULL COMMENT '文件id',
                                         `qm_segment_id` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'dify段落id',
                                         `position` int(11) NULL DEFAULT NULL COMMENT '位置',
                                         `qm_document_id` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'dify所属文档ID',
                                         `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '分段内容文本',
                                         `sign_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '签名内容文本',
                                         `answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '答案内容(如果有)',
                                         `word_count` int(11) NULL DEFAULT NULL COMMENT '内容长度',
                                         `tokens` int(11) NULL DEFAULT NULL COMMENT 'token数量',
                                         `keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '关键词',
                                         `index_node_id` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '索引节点ID',
                                         `index_node_hash` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '索引节点哈希值',
                                         `hit_count` int(11) NULL DEFAULT NULL COMMENT '访问次数',
                                         `enabled` tinyint(1) NULL DEFAULT NULL COMMENT '启用状态',
                                         `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态',
                                         `completed_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '完成时间戳',
                                         `error` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '错误信息',
                                         `child_chunks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '子模块',
                                         `sync_status` tinyint(3) UNSIGNED NULL DEFAULT 0 COMMENT '分段添加dify状态;0-添加中、1-添加成功、2-添加失败',
                                         `parent_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父级id',
                                         `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                         `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                         `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                                         `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                         `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                         `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                                         `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                         `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                         `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                                         PRIMARY KEY (`id`) USING BTREE,
                                         INDEX `idx_document_id`(`document_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 371 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '文件分段' ROW_FORMAT = DYNAMIC;

