INSERT INTO `kmc_document_segment` VALUES (352, 1001, '01_设备基础知识.docx', 40, '65792969-e160-46ef-8aab-e3a0d2ea7fcd', 1, NULL, '设备基础知识 - 泵站设备故障诊断知识库\n设备基础知识\n泵站设备故障诊断知识库\n分类：知识类/设备基础知识\r\n泵站设备基础知识用于统一运维人员对主要设备、关键部件和运行参数的理解，是后续故障诊断、案例沉淀和维修决策的基础。\n一、知识内容\n主要设备组成\n• 水泵：负责将水体加压输送，是泵站的核心动力设备。\n• 电机：为水泵提供旋转动力，需关注电流、温升、绝缘和振动。\n• 管道与阀门：承担输水、截断、调节和防倒流功能。\n• 传感器与仪表：采集压力、流量、液位、温度、振动、电流等状态数据。\n• 控制柜与变频器：完成启停控制、联锁保护、调速和报警。\n关键运行参数\n二、结构化知识表\n	参数\n	含义\n	异常提示\r\n	流量\n	单位时间内输送水量\n	流量下降可能与堵塞、阀门未开足、叶轮磨损有关\r\n	扬程/压力\n	泵提升水体的能力\n	压力不足可能与汽蚀、漏气、管路阻力异常有关\r\n	振动\n	反映设备机械状态\n	振动增大可能提示轴承、联轴器、地脚或不平衡问题\r\n	温度\n	电机、轴承、密封等部位热状态\n	温升过快可能与润滑不良、负载过大、散热差有关\r\n	电流\n	电机运行负荷指标\n	电流异常可能与过载、缺相、堵转或电气故障有关\r\n三、上传与检索建议\n• 建议上传分类：知识类/设备基础知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '设备基础知识 - 泵站设备故障诊断知识库\n设备基础知识\n泵站设备故障诊断知识库\n分类：知识类/设备基础知识\r\n泵站设备基础知识用于统一运维人员对主要设备、关键部件和运行参数的理解，是后续故障诊断、案例沉淀和维修决策的基础。\n一、知识内容\n主要设备组成\n• 水泵：负责将水体加压输送，是泵站的核心动力设备。\n• 电机：为水泵提供旋转动力，需关注电流、温升、绝缘和振动。\n• 管道与阀门：承担输水、截断、调节和防倒流功能。\n• 传感器与仪表：采集压力、流量、液位、温度、振动、电流等状态数据。\n• 控制柜与变频器：完成启停控制、联锁保护、调速和报警。\n关键运行参数\n二、结构化知识表\n	参数\n	含义\n	异常提示\r\n	流量\n	单位时间内输送水量\n	流量下降可能与堵塞、阀门未开足、叶轮磨损有关\r\n	扬程/压力\n	泵提升水体的能力\n	压力不足可能与汽蚀、漏气、管路阻力异常有关\r\n	振动\n	反映设备机械状态\n	振动增大可能提示轴承、联轴器、地脚或不平衡问题\r\n	温度\n	电机、轴承、密封等部位热状态\n	温升过快可能与润滑不良、负载过大、散热差有关\r\n	电流\n	电机运行负荷指标\n	电流异常可能与过载、缺相、堵转或电气故障有关\r\n三、上传与检索建议\n• 建议上传分类：知识类/设备基础知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 1, 1, NULL, NULL, '2026-06-01 15:05:00', NULL, NULL, '2026-06-01 15:05:00', NULL);
